import{z as d,x as s,o as t,c as l,q as A,j as i,D as E,d as n,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"交错 DiD 的最新修正","description":"","frontmatter":{"title":"交错 DiD 的最新修正","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-staggered-did-revisions.md","filePath":"econ/pe-staggered-did-revisions.md","lastUpdated":1791413859000}'),m={name:"econ/pe-staggered-did-revisions.md"};function p(D,a,T,c,h,u){const r=s("Mermaid");return t(),l("div",null,[a[2]||(a[2]=A('<h1 id="交错-did-的最新修正" tabindex="-1">交错 DiD 的最新修正 <a class="header-anchor" href="#交错-did-的最新修正" aria-label="Permalink to &quot;交错 DiD 的最新修正&quot;">​</a></h1><div class="epigraph"><p>TWFE 的错不是算错，是答错题：它一直在认真估计一个没人要的加权。修正潮的全部工作，是先把题写清楚——报哪个参数、拿谁当对照、按什么聚合。</p><footer>—— Goodman-Bacon, J. Econometrics 2021；Callaway and Sant&#39;Anna, J. Econometrics 2021；Sun and Abraham, Econometrica 2021</footer></div><p><a href="/econ/pe-eventstudy-specification">上一课</a>把事件图钉在参照期、端点与队列三个选择上，队列问题被推到本课。主干<a href="/econ/staggered-did">交错 DiD</a> 已给出 Goodman-Bacon 分解与「只用干净对照」的原则；本课把 2021 年前后的修正收成一套可执行的工序：诊断、定目标、选对照、聚合、推断。修订不是每年换一个新估计量，而是同一个原则在不同数据形态下的落法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分解是诊断，不是终点。Bacon 分解告诉你 TWFE 的 \\(\\hat\\beta\\) 里混了多少「已处理当对照」的 \\(2\\times2\\)，但它不回答该报什么。真正的工作从目标开始：同一组队列–时点效应 \\(\\mathrm{ATT}(g,t)\\)，聚合方式不同，讲的是不同的故事——按事件时点聚合给动态路径，按采纳组聚合给组间分布，按日历时间聚合给当期总效应。不先定聚合，软件默认给的那一个数就被当成了「这个政策的效应」。第二个问题是对照的选择：never-treated 组最稳但可能不存在或太小；not-yet-treated 组样本多、功效高，但要求「尚未处理」本身是干净的——预期若已让他们提前行动，对照组照样被污染。<span class="marginnote">直觉类比：拿 not-yet-treated 当对照，像拿「下学期也要补习、但现在还没开始」的同学当基线。若他知道自己迟早要补，现在的学习行为可能已经变了——「还没处理」不等于「没受影响」，预期效应从基线里漏进来，对照就不干净了。</span>第三个问题是数据形态：处理有开关（进入又退出）、有剂量（处理强度连续）时，各估计量的保证范围不同，超出范围的用法要标注而不是硬跑。</p><p><span class="marginnote">功效的枯竭要提前看见：not-yet-treated 对照把功效买在「尚无人处理」的早期窗口；采纳图上晚期进入者占多数、never-treated 缺席的设计，后期 \\(\\mathrm{ATT}(g,t)\\) 会面临无对照可用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工序六步。第一，画采纳图：队列、处理开关与退出全在图上。第二，诊断：报 Bacon 分解或负权重份额，让「TWFE 不能用」成为有数字的陈述。第三，定聚合目标：政策问题要的是动态、组分布还是当期存量，先写下来。<span class="marginnote">术语翻译：\\(\\mathrm{ATT}(g,t)\\) 读作「第 \\(g\\) 批采纳者在第 \\(t\\) 期的平均效应」——它是矩阵里的一个小格子。所谓聚合，就是把几百个小格子按不同权重平均成一个大数：按「处理后过了几期」平均得到动态路径，按「哪一批人」平均得到组间分布，按「今年是哪一年」平均得到当期存量。权重一换，故事就换。</span>第四，选对照：有 never-treated 用之；没有则用 not-yet-treated 并声明预期风险。第五，估计：Callaway–Sant&#39;Anna 在协变量下做条件平行趋势，倾向得分与回归双稳健并用；Borusyak、Jaravel 与 Spiess 的填补估计量用未处理格点估 \\(\\alpha_i+\\lambda_t\\) 再外推，功效最高，代价是把模型推到已处理格点上；Sun–Abraham 的交互加权用在事件研究展示上。处理开关与剂量转给 de Chaisemartin–D&#39;Haultfœuille 的框架。第六，推断：政策在群层就群层聚类，注意组内序列相关，路径图接上一课的四件套报告。</p>',8)),(t(),i(o,null,{default:E(()=>[B(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22%E7%94%BB%E9%87%87%E7%BA%B3%E5%9B%BE%3A%20%E9%98%9F%E5%88%97%E4%B8%8E%E5%BC%80%E5%85%B3%22%5D%20--%3E%20DIAG%5B%22Bacon%20%E5%88%86%E8%A7%A3%E6%88%96%E8%B4%9F%E6%9D%83%E9%87%8D%E8%AF%8A%E6%96%AD%22%5D%0A%20%20DIAG%20--%3E%20TGT%5B%22%E5%AE%9A%E8%81%9A%E5%90%88%E7%9B%AE%E6%A0%87%3A%20%E5%8A%A8%E6%80%81%2F%E7%BB%84%2F%E6%97%A5%E5%8E%86%22%5D%0A%20%20TGT%20--%3E%20CTRL%7B%22never-treated%20%E5%AD%98%E5%9C%A8%3F%22%7D%0A%20%20CTRL%20--%3E%7C%E6%98%AF%7C%20CS%5B%22CS%3A%20%E5%8F%8C%E9%87%8D%E7%A8%B3%E5%81%A5%20ATT(g%2Ct)%22%5D%0A%20%20CTRL%20--%3E%7C%E5%90%A6%7C%20NY%5B%22not-yet-treated%20%E5%AF%B9%E7%85%A7%E5%B9%B6%E5%A3%B0%E6%98%8E%E9%A2%84%E6%9C%9F%E9%A3%8E%E9%99%A9%22%5D%0A%20%20CS%20--%3E%20AGG%5B%22%E6%98%BE%E5%BC%8F%E8%81%9A%E5%90%88%22%5D%0A%20%20NY%20--%3E%20AGG%0A%20%20AGG%20--%3E%20INF%5B%22%E7%BE%A4%E5%B1%82%E8%81%9A%E7%B1%BB%E4%B8%8E%E8%B7%AF%E5%BE%84%E5%9B%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是加权权从哪里来。TWFE 的权重由回归代数（残差化的处理方差）给出，符号不定；新估计量的权重由目标函数给出——你选了要平均的组与时点，权重就是你选的。这一换把「估计什么」从软件手里拿回研究者手里。两个假设各守一扇门：干净对照挡住已处理组当反事实，「无预期」挡住提前反应把效应搬进处理前；上一课的换参照检查与这一课的 not-yet 风险是同一扇门的两把锁。",-1)),a[5]||(a[5]=e("p",null,"不这么做会错在哪：只报诊断不换估计量，论文停在「TWFE 有问题」；换估计量不定聚合，三个数字各讲各的故事，审稿与读者各自挑一个用。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者看到「负权重」以为是软件 bug 或数值误差。实际上负权重是 TWFE 加权代数的固有结果——有些「已处理当对照」的 \\(2\\times2\\) 被赋了负号，于是 \\(\\hat\\beta\\) 可以落在所有单个 \\(2\\times2\\) 估计的取值范围之外：它不是哪个真实效应的估计，是没有人要的加权混合。")],-1)),(t(),i(o,null,{default:E(()=>[B(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BA%5B%22TWFE%20%3D%20%E4%B8%80%E5%A0%86%202x2%20%E6%AF%94%E8%BE%83%E7%9A%84%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%22%5D%20--%3E%20G1%5B%22%E5%B9%B2%E5%87%80%E5%AF%B9%E7%85%A7%3A%20%E5%A4%84%E7%90%86%E7%BB%84%20vs%20%E5%B0%9A%E6%9C%AA%E5%A4%84%E7%90%86%E7%BB%84%22%5D%0A%20%20BA%20--%3E%20G2%5B%22%E8%84%8F%E5%AF%B9%E7%85%A7%3A%20%E5%A4%84%E7%90%86%E7%BB%84%20vs%20%E5%B7%B2%E5%A4%84%E7%90%86%E6%9B%B4%E4%B9%85%E7%9A%84%E7%BB%84%22%5D%0A%20%20G1%20--%3E%20OK%5B%22%E6%9D%83%E9%87%8D%E4%B8%BA%E6%AD%A3%2C%20%E5%8D%95%E4%B8%AA%E6%AF%94%E8%BE%83%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20G2%20--%3E%20NEG%5B%22%E5%B7%B2%E5%A4%84%E7%90%86%E7%BB%84%E7%9A%84%E6%95%88%E5%BA%94%E6%B3%84%E8%BF%9B%E5%AF%B9%E7%85%A7%2C%20%E6%9D%83%E9%87%8D%E5%8F%AF%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20OK%20--%3E%20MIX%5B%22beta%20%E6%B7%B7%E5%90%88%E5%90%8E%E6%97%A0%E5%8D%95%E4%B8%80%E6%94%BF%E7%AD%96%E5%90%AB%E4%B9%89%22%5D%0A%20%20NEG%20--%3E%20MIX%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>上图回答的问题是 TWFE 的错「错在哪一格」：工序图画修正怎么执行，这张把 Bacon 分解画成分解图——同一个 \\(\\hat\\beta\\) 里干净与脏两类比较按不定号权重搅在一起；诊断（负权重份额）量的就是脏格子占了多少，修正估计量做的就是把脏格子从对照池里除名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣称某个新估计量全域最优：never-treated 充足时各种修正收敛到相近答案，分歧都在对照枯竭与开关剂量处。连续处理与 anticipated treatment 的完整代数不展开，只标接口。两期两组的 DiD 沿主干口径，不需要修正。修正是让估计对准目标，不是让所有研究得出同一个数。</p><p>后课默认：交错面板先诊断、定目标、选对照，再谈数字；下一课换截面门槛设计，不再拆时间加权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分解是诊断；修正是目标先行：动态、组分布、日历存量，先选一个。</li><li>对照只用 never-treated 或干净的 not-yet-treated，并声明预期风险。</li><li>CS 双重稳健、填补法高功效、Sun–Abraham 管事件图；开关与剂量另有框架。</li><li>权重由目标函数给，不从软件默认里读结论。</li><li>出处：Goodman-Bacon 2021；Callaway and Sant&#39;Anna 2021；Sun and Abraham 2021；de Chaisemartin and D&#39;Haultfœuille 2020。</li></ul>',6))])}const f=d(m,[["render",p]]);export{C as __pageData,f as default};
